mapper.select:
SELECT COUNT(*)
FROM bundle
WHERE category_id = #{categoryId}

SELECT b.id, b.name, b.category_id, c.name AS categoryName, b.price, b.image, b.description, b.status, b.storage_zone, b.update_time FROM bundle b LEFT JOIN goods_category c ON c.id = b.category_id
AND b.name LIKE CONCAT('%', #{name}, '%')
AND b.category_id = #{categoryId}
AND b.status = #{status}
ORDER BY b.update_time DESC

mapper.update:
UPDATE bundle
category_id = #{categoryId}, name = #{name}, price = #{price}, description = #{description}, image = #{image}, storage_zone = #{storageZone}, update_time = #{updateTime}, update_user = #{updateUser}
WHERE id = #{id}

UPDATE bundle
SET status      = #{status},
    update_time = #{updateTime},
    update_user = #{updateUser}
WHERE id = #{id}

